function representedMarkets(items){var found={};items.forEach(function(x){models(x).forEach(function(m){var q=m.raw||{},z=[q.primary_market_label,q.market,q.market_name,q.representation_market,q.location].concat(arr(q.markets),arr(q.market_assignments),arr(q.model_market_assignments)).map(function(v){return String(v&&((v.markets&&v.markets.name)||v.name||v.market_name)||v||'');}).join(' ').toLowerCase();if(/new york|nyc|jfk/.test(z))found['New York']=1;if(/paris|france|cdg/.test(z))found.Paris=1;});});if(!Object.keys(found).length)items.forEach(function(x){found[market(x)]=1;});return ['New York','Paris'].filter(function(m){return found[m];});}
