function value(x){var r=x.raw||{},rates=arr(r.booking_rates);if(rates.length)return rates.reduce(function(n,v){var gross=Number(v.talent_gross);if(isFinite(gross)&&gross>0)return n+gross;return n+(Number(v.quantity)||1)*(Number(v.unit_amount)||0);},0);var meta=r.metadata||{},direct=[meta.pay_amount,r.pay_amount,r.rate_amount,r.total_amount,r.gross_amount,r.amount,r.fee,r.booking_fee];for(var i=0;i<direct.length;i++){var n=Number(direct[i]);if(isFinite(n)&&n>0)return n;}var note=String(r.rate_note||'').replace(/[^0-9.\-]/g,'');var parsed=Number(note);return isFinite(parsed)&&parsed>0?parsed:0;}

function currencyOf(x){var r=x.raw||{},rates=arr(r.booking_rates),m=r.metadata||{};return String((rates[0]&&rates[0].currency)||r.currency||m.currency||'USD').slice(0,3).toUpperCase();}
function paymentStatus(x){var r=x.raw||{},m=r.metadata||{};if(m.paid===true||m.payment_status==='paid'||r.payment_status==='paid')return 'Paid';if(m.payment_status)return String(m.payment_status).replace(/_/g,' ');if(r.payment_status)return String(r.payment_status).replace(/_/g,' ');return value(x)>0?'Rate connected':'No payment status';}
function financeState(x){var r=x.raw||{},inv=arr(r.invoices||r.finance_invoices),m=r.metadata||{};if(inv.length){var i=inv[0];return [i.invoice_number||'Invoice',i.status||'',i.amount_due!=null?money(i.amount_due,i.currency||currencyOf(x),false)+' due':''].filter(Boolean).join(' · ');}if(m.invoice_id||r.invoice_id)return 'Invoice connected';if(x.kind==='booking'&&value(x)>0)return 'Ready for Finance / invoice';if(value(x)>0)return 'Pay amount recorded';return 'No finance amount';}

function evaluationFor(name){var found=null;S.items.some(function(x){return models(x).some(function(m){if(m.name===name&&m.raw&&m.raw.latest_evaluation){found=m.raw.latest_evaluation;return true;}return false;});});return found;}
function ratingLabel(e){if(!e||e.overall_current==null)return 'Not rated';var n=Number(e.overall_current);return isFinite(n)?(n<=10?n.toFixed(1)+' / 10':Math.round(n)+'%'):'Not rated';}
function modelNames(){var seen={};S.items.forEach(function(x){models(x).forEach(function(m){seen[m.name]=m;});});return Object.keys(seen).sort(function(a,b){return a.localeCompare(b);});}
