async function loadSeasons(force){if(!force&&S.seasonAt&&Date.now()-S.seasonAt<60000)return;try{var d=await window.VEUX_AGENT_V4.api('/api/agent/season/v9?organization='+encodeURIComponent(org()),{method:'GET',headers:{},__fresh:true});S.seasonList=arr(d.seasons).map(function(x){return {id:x.id,name:x.name,starts_on:x.starts_on,ends_on:x.ends_on,market:x.markets&&x.markets.name||''};});var byId={};arr(d.seasons).forEach(function(x){byId[x.id]=x;});S.seasonShows=arr(d.shows).filter(function(x){return x.starts_at;}).map(function(x){var n=String(x.notes||''),kind=(n.match(/kind=(\w+)/)||[])[1]||'show',ends=(n.match(/ends=([^;]+)/)||[])[1]||'',se=byId[x.season_id]||{};return {kind:'show',id:x.id,title:x.title,starts_at:x.starts_at,ends_at:ends||null,status:x.status||'planned',location:x.location||'',market:se.markets&&se.markets.name||'',client:x.companies&&x.companies.name||'',models:arr(x.season_show_models),notes:x.notes||'',raw:{id:x.id,season_id:x.season_id,company_id:x.company_id||null,season_name:se.name||'',show_kind:kind,metadata:{calendar_event_type:kind==='presentation'?'Presentation':'Fashion Show'},status:x.status}};});S.seasonAt=Date.now();}catch(e){S.seasonList=S.seasonList||[];}}
