function uq(l){var seen={};return (l||[]).filter(function(x){var k=x.kind+'|'+x.id;return seen[k]?false:(seen[k]=1);});}
function spreadDays(list){var out=list.slice();list.forEach(function(x){if(x.kind==='show'||!x.ends_at)return;var s=new Date(x.starts_at),e=new Date(x.ends_at);if(isNaN(s)||isNaN(e)||e<=s)return;var last=new Date(e);if(!last.getHours()&&!last.getMinutes()&&!last.getSeconds()&&!last.getMilliseconds())last=new Date(+last-1);var d0=new Date(s.getFullYear(),s.getMonth(),s.getDate()),d1=new Date(last.getFullYear(),last.getMonth(),last.getDate()),n=0,t=new Date(d0);while(t<d1&&n<62){t.setDate(t.getDate()+1);n++;}if(!n)return;x._days=n+1;for(var i=1;i<=n;i++){var day=new Date(d0);day.setDate(day.getDate()+i);var next=new Date(day);next.setDate(next.getDate()+1);out.push(Object.assign({},x,{title:x.title+' · day '+(i+1)+' of '+(n+1),starts_at:day.toISOString(),ends_at:(i===n?e:next).toISOString(),_cont:true,_day:i+1,_days:n+1}));}});return out;}
function normalize(d){var out=[];function push(kind,x){out.push({kind:kind,id:x.id,title:x.title||x.job_title||(kind==='booking'?'Booking':kind==='casting'?'Casting':'Event'),starts_at:x.starts_at,ends_at:x.ends_at,status:x.status||'',location:x.location||'',market:x.markets&&x.markets.name||x.market_name||x.market||'',client:x.companies&&x.companies.name||x.client_name||'',models:x[kind+'_models']||x.model_assignments||[],notes:x.internal_notes||x.brief||x.notes||'',raw:x});}arr(d.bookings).forEach(push.bind(null,'booking'));arr(d.castings).forEach(push.bind(null,'casting'));arr(d.events).forEach(push.bind(null,'event'));S.people=teamOf(out);if(S.person!=='all'&&S.people.indexOf(S.person)<0)S.person='all';return spreadDays(out.filter(function(x){return x.starts_at&&onPersonCalendar(x);})).sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);});}
function period(){var r=range();if(S.view==='month')return date(S.anchor,{month:'long',year:'numeric'});if(S.view==='plan')return date(r.start)+' – '+date(add(r.start,6));if(S.view==='week')return date(r.start)+' – '+date(r.end);if(S.view==='3day'||S.view==='agenda')return date(r.start)+' – '+date(r.end);return date(S.anchor,{weekday:'long',month:'long',day:'numeric'});}
