function controls(){var names=modelNames(),label=S.model==='all'?'All Models':S.model,scopeSub=S.model==='all'?'Agency-wide calendar intelligence':'Model-only calendar · no other talent shown';return '<header class="vx75-control vx161115-calendar-command"><div class="vx75-identity"><small>'+eyebrow()+'</small><h1>'+title()+'</h1>'+calSwitch()+'</div><div class="vx75-date"><button data-act="move" data-n="-1" aria-label="Previous period">‹</button><button data-act="today">Today</button><strong>'+esc(period())+'</strong><button data-act="move" data-n="1" aria-label="Next period">›</button></div><div class="vx75-tabs">'+[['plan','Agenda'],['day','Orbit'],['month','Month']].map(function(v){return '<button data-view="'+v[0]+'" class="'+(S.view===v[0]?'on':'')+'">'+v[1]+'</button>';}).join('')+'</div><button class="vx75-add" data-act="add">Add event <b>＋</b></button></header><div class="vx76-scopebar vx84-scopebar vx1047-scopebar"><div class="vx1047-scope-lead"><span class="vx1047-scope-icon">◎</span><span class="vx1047-scope-copy"><small>Calendar Scope</small><b>'+esc(label)+'</b><em>'+esc(scopeSub)+'</em></span></div><div class="vx1047-scope-actions"><button class="vx84-agency vx1047-agency '+(S.model==='all'?'on':'')+'" data-model="all" aria-label="Show full agency calendar"><i>◉</i><span><small>View</small><b>Agency</b></span><em>'+names.length+'</em></button><div class="vx82-picker vx84-model-picker vx1047-model-picker"><label class="vx82-search vx1047-search"><i>⌕</i><span><small>Model calendar</small><input data-model-search value="'+esc(S.model==='all'?'':S.model)+'" placeholder="Search model…" autocomplete="off"></span></label><button type="button" data-act="toggle-models" aria-label="Open model calendar selector"><span>Browse</span><i>⌄</i></button><div class="vx82-picker-menu"><header><small>Model Calendars</small><b>'+names.length+' active</b></header><button type="button" data-model="all" class="'+(S.model==='all'?'on':'')+'">Agency Calendar · All Models</button>'+names.map(function(n){return '<button type="button" data-model="'+esc(n)+'" class="'+(S.model===n?'on':'')+'">'+esc(n)+'</button>';}).join('')+'</div></div></div><div class="vx84-scope-state vx1047-scope-state"><small>Current View</small><b>'+esc(S.model==='all'?'Agency Operations':S.model)+'</b><span>'+(S.model==='all'?'All model movements and agency intelligence':esc('Private model schedule only'))+'</span></div></div>';}
