function eventButton(x,cls){var selected=S.selected&&S.selected.kind===x.kind&&String(S.selected.id)===String(x.id),amt=value(x);return '<button class="vx75-event '+(cls||'')+' '+tone(x)+(selected?' selected':'')+'" data-event="'+esc(x.kind)+'|'+esc(x.id)+'"'+dragAttrs(x)+' aria-label="'+esc(time(x.starts_at)+' '+x.title+' '+(x.status||'scheduled'))+'"><small>'+esc(time(x.starts_at))+' · '+esc(type(x))+(amt?' · '+esc(money(amt,currencyOf(x),false)):'')+'</small><b>'+esc(x.title)+'</b><span>'+esc([x.client,x.location].filter(Boolean).join(' · '))+'</span></button>';}
/* Background, not a timed commitment: a day of a long stay, anything running 20 hours or more, or a date-only marker (starts at midnight with no end). */
function bgSpan(x){var s=new Date(x.starts_at),e=x.ends_at?new Date(x.ends_at):null;if(isNaN(s))return false;if(x._cont||x._days>1)return true;if(e&&e-s>=20*36e5)return true;return !e&&!s.getHours()&&!s.getMinutes()&&!s.getSeconds();}
