/* ---------- Agenda: a time-first, day-grouped timeline ---------- */
function agendaSpan(){var n=Number(S.agendaDays);return n===7||n===30?n:14;}
function agendaDur(a,b){var m=Math.round((new Date(b)-new Date(a))/60000);if(!isFinite(m)||m<=0)return '';var h=Math.floor(m/60),r=m%60;return h?(h+'h'+(r?' '+r+'m':'')):(r+'m');}
