      callRaw=x.raw&&(x.raw.call_time||(x.raw.metadata&&x.raw.metadata.call_time)),call=callRaw&&time(callRaw)!==time(x.starts_at)?time(callRaw):'',amt=value(x),awaiting=agendaAwaiting(x),
      vm=(x.raw&&x.raw.metadata)||{},visaLock=!!vm.visa_blocking,visaMsg=vm.visa_gate_message||'Visa not cleared — travel locked',past=(en||st).getTime()<nowMs,live=!bgSpan(x)&&st.getTime()<=nowMs&&(en||new Date(st.getTime()+3600000)).getTime()>=nowMs;
  var av=ms.slice(0,3).map(function(m){return '<span class="mdv-ag-av" title="'+esc(m.name)+'">'+avatar(m)+'</span>';}).join('')+(ms.length>3?'<span class="mdv-ag-more">+'+(ms.length-3)+'</span>':'');
  return '<button type="button" class="mdv-ag-row '+tone(x)+(past?' past':'')+(live?' live':'')+'" data-open="'+esc(x.kind)+'|'+esc(x.id)+'">'
    +'<span class="mdv-ag-time"><b>'+esc(time(x.starts_at))+'</b>'+(en?'<small>'+esc(time(x.ends_at))+'</small>':'')+(dur?'<em>'+esc(dur)+'</em>':'')+'</span>'
    +'<span class="mdv-ag-rail"><i></i></span>'
    +'<span class="mdv-ag-card"><span class="mdv-ag-top"><span class="mdv-ag-type">'+esc(type(x))+'</span>'+(live?'<span class="mdv-ag-flag now">Happening now</span>':'')+(call?'<span class="mdv-ag-flag">Call '+esc(call)+'</span>':'')+(clash.length?'<span class="mdv-ag-flag risk" title="'+esc(clash.map(function(c){return c.title;}).join(', '))+'">Overlap</span>':'')+(awaiting?'<span class="mdv-ag-flag wait">Awaiting reply</span>':'')+(visaLock?'<span class="mdv-ag-flag risk" title="'+esc(visaMsg)+'">Visa locked</span>':'')+'</span>'
    +'<b class="mdv-ag-title">'+esc(x.title||'Untitled')+'</b>'
