    +'<span class="mdv-ag-foot"><span class="mdv-ag-people">'+(av||'<small>No models yet</small>')+(ms.length===1?'<small>'+esc(ms[0].name)+'</small>':ms.length>1?'<small>'+ms.length+' models</small>':'')+'</span>'
    +'<span class="mdv-ag-end">'+(amt?'<b>'+esc(money(amt,currencyOf(x),false))+'</b>':'')+'<span class="mdv-ag-status">'+esc(runwayStatus(x))+'</span></span></span></span></button>';
