/* ---------- Agent tasks (replaces "Coming up") ---------- */
var TK={list:null,members:[],loading:false,err:'',scope:'mine',me:null};
function tkUid(){try{var st=window.VEUX_AGENT_V4.state;return (st.user&&st.user.id)||(st.session&&st.session.user&&st.session.user.id)||(st.profile&&st.profile.user_id)||null;}catch(e){return null;}}
function tkDiff(iso){if(!iso)return null;var d=new Date(iso);if(isNaN(d))return null;var a=new Date(d.getFullYear(),d.getMonth(),d.getDate()),n=new Date();n=new Date(n.getFullYear(),n.getMonth(),n.getDate());return Math.round((a-n)/864e5);}
function tkDue(iso){var d=tkDiff(iso);if(d==null)return '';if(d===0)return 'Today';if(d===1)return 'Tomorrow';if(d===-1)return 'Yesterday';return date(iso,{month:'short',day:'numeric'});}
async function loadTasks(force){
  if(TK.loading||(TK.list&&!force))return;TK.loading=true;
  try{
    var d=await window.VEUX_AGENT_V4.api('/api/agent/tasks/v11?organization='+encodeURIComponent(org())+'&_t='+Date.now(),{method:'GET',headers:{},__fresh:true});
    TK.members=arr(d.members);var u=tkUid();TK.me=u?(TK.members.filter(function(m){return m.user_id===u;})[0]||null):null;
    if(!TK.me&&TK.scope==='mine')TK.scope='all';
    TK.list=arr(d.tasks).filter(function(t){return !t.parent_task_id;});TK.err='';
  }catch(e){TK.err=(e&&e.message)||'Tasks could not load';TK.list=TK.list||[];}
  TK.loading=false;paintTasks();paintModels();paintOrbitTasks();
}
function tkMine(t){return !!TK.me&&arr(t.assignments).some(function(a){return a.member_id===TK.me.id;});}
function tkOpen(){return arr(TK.list).filter(function(t){var s=String(t.status||'open').toLowerCase();return s!=='completed'&&s!=='done'&&s!=='complete'&&s!=='cancelled'&&s!=='canceled';}).filter(function(t){return TK.scope==='all'||tkMine(t);});}
function tasksHtml(sel){
  if(!TK.list){loadTasks();return '<header><h3>Agent tasks</h3></header><p class="pl-none">Loading tasks…</p>';}
  var open=tkOpen().sort(function(a,b){var x=a.due_at?new Date(a.due_at):new Date(8e15),y=b.due_at?new Date(b.due_at):new Date(8e15);return x-y;});
  var G=[['over','Overdue'],['today','Today'],['week','Next 7 days'],['later','Later'],['none','No date']],by={over:[],today:[],week:[],later:[],none:[]};
  open.forEach(function(t){var d=tkDiff(t.due_at);by[d==null?'none':d<0?'over':d===0?'today':d<=7?'week':'later'].push(t);});
  var rank={urgent:'u',high:'h'};
  function row(t){var d=tkDiff(t.due_at),pr=rank[String(t.priority||'').toLowerCase()]||'';return '<div class="tk-row'+(d!=null&&d<0?' over':'')+'"><button type="button" class="tk-check" data-tk-done="'+esc(t.id)+'" aria-label="Mark done"></button><button type="button" class="tk-title" data-tk-open="'+esc(t.id)+'">'+esc(t.title||'Untitled')+'</button>'+(pr?'<i class="tk-pr '+pr+'" title="'+(pr==='u'?'Urgent':'High')+'"></i>':'')+(t.due_at?'<em>'+esc(tkDue(t.due_at))+'</em>':'')+'</div>';}
  var body=G.map(function(g){var l=by[g[0]];if(!l.length)return '';var shown=l.slice(0,g[0]==='later'||g[0]==='none'?3:6);return '<div class="tk-grp'+(g[0]==='over'?' over':'')+'"><h4>'+g[1]+' <em>'+l.length+'</em></h4>'+shown.map(row).join('')+(l.length>shown.length?'<button type="button" class="tk-more" data-tk-open="">+ '+(l.length-shown.length)+' more</button>':'')+'</div>';}).join('');
  if(!open.length)body='<p class="pl-none">'+(TK.err?esc(TK.err):'No open tasks. Nice work.')+'</p>';
  var sd=sel?date(new Date(sel+'T12:00:00'),{weekday:'short',month:'short',day:'numeric'}):'';
  return '<header><h3>Agent tasks</h3><span class="tk-count">'+open.length+' open'+(by.over.length?' · <b>'+by.over.length+' overdue</b>':'')+'</span><div class="pl-seg"><button type="button" class="'+(TK.scope==='mine'?'on':'')+'" data-tk-scope="mine"'+(TK.me?'':' disabled')+'>Mine</button><button type="button" class="'+(TK.scope==='all'?'on':'')+'" data-tk-scope="all">Everyone</button></div></header>'
    +'<form class="tk-add" data-tk-add><input type="text" maxlength="200" placeholder="Add a task for '+esc(sd)+'…" aria-label="New task"><button type="submit">Add</button></form>'
    +'<div class="tk-list">'+body+'</div><footer><button type="button" class="tk-all" data-tk-open="">Open all tasks →</button></footer>';
}
function paintTasks(){var el=document.getElementById('pl-tasks');if(el)el.innerHTML=tasksHtml(el.dataset.tkday);}
document.addEventListener('click',function(e){
  var t=e.target&&e.target.closest&&e.target.closest('#pl-tasks [data-tk-scope],#pl-tasks [data-tk-done],#pl-tasks [data-tk-open]');if(!t)return;
  if(t.dataset.tkScope){TK.scope=t.dataset.tkScope;paintTasks();return;}
  if(t.hasAttribute('data-tk-open')){if(typeof window.navTo==='function')window.navTo('tasksconsolidated');return;}
  if(t.dataset.tkDone){var id=t.dataset.tkDone,task=arr(TK.list).filter(function(x){return String(x.id)===id;})[0];if(!task)return;var prev=task.status;task.status='completed';paintTasks();
    window.VEUX_AGENT_V4.api('/api/agent/tasks/v11',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({organization_slug:org(),action:'task_status',task_id:id,status:'completed'})}).then(function(r){if(!r||r.verified!==true)throw new Error('Not verified');toastMove('Task done');}).catch(function(err){task.status=prev;paintTasks();toastMove('Could not save: '+(err&&err.message||err),true);});}
});
document.addEventListener('submit',function(e){
  var f=e.target&&e.target.closest&&e.target.closest('#pl-tasks [data-tk-add]');if(!f)return;e.preventDefault();
  var inp=f.querySelector('input'),title=inp.value.trim();if(!title)return;var box=document.getElementById('pl-tasks'),day=box&&box.dataset.tkday;
  var body={organization_slug:org(),action:'create_task',title:title,priority:'normal',category:null,member_ids:TK.me?[TK.me.id]:[]};if(day)body.due_at=new Date(day+'T12:00:00').toISOString();
  inp.disabled=true;
  window.VEUX_AGENT_V4.api('/api/agent/tasks/v11',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}).then(function(r){if(!r||r.verified!==true)throw new Error('Not verified');toastMove('Task added');var t=r.task;if(t&&t.id){t.assignments=TK.me?[{member_id:TK.me.id}]:[];TK.list=arr(TK.list).concat([t]);paintTasks();paintModels();}else TK.list=null;return loadTasks(true);}).catch(function(err){inp.disabled=false;toastMove('Could not add: '+(err&&err.message||err),true);});
});
/* ---------- Model plans and movement: what each model has due and where they are moving, beside the day ---------- */
var MP={scope:'week',last:null};
function mpIsMove(x){var q=(type(x)+' '+(x.title||'')+' '+((x.raw&&x.raw.metadata&&x.raw.metadata.event_kind)||'')).toLowerCase();return agendaKindOf(x)==='travel'||/visa|arriv|depart|flight|housing|airport|\bstay\b/.test(q);}
function mpOpenTask(t){var s=String(t.status||'open').toLowerCase();return s!=='completed'&&s!=='done'&&s!=='complete'&&s!=='cancelled'&&s!=='canceled';}
function mpLabel(t){var c=(t.metadata&&t.metadata.task_type)||t.category||'';return String(c).replace(/_/g,' ').replace(/^./,function(m){return m.toUpperCase();});}
function modelsHtml(items,weekKeys,sel){
  MP.last={items:items,weekKeys:weekKeys,sel:sel};
  var day=MP.scope==='day',inRange=function(k){return day?k===sel:weekKeys.indexOf(k)>=0;};
  var hdr='<header><h3>Model plans &amp; movement</h3><span class="tk-count">'+(day?'This day':'This week')+'</span><div class="pl-seg"><button type="button" class="'+(day?'':'on')+'" data-mp-scope="week">Week</button><button type="button" class="'+(day?'on':'')+'" data-mp-scope="day">Day</button></div></header>';
  if(!TK.list){loadTasks();return hdr+'<p class="pl-none">Loading plans…</p>';}
  var lookups={};arr(S.data&&S.data.lookups&&S.data.lookups.models).forEach(function(m){lookups[m.id]=m;});
  var move=items.filter(function(x){return mpIsMove(x)&&inRange(key(x.starts_at));}).sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);});
  var now=Date.now(),byModel={};
  arr(TK.list).filter(function(t){return t.model_id&&lookups[t.model_id]&&mpOpenTask(t)&&t.due_at;}).forEach(function(t){
    var nm=lookups[t.model_id].display_name;if(S.model!=='all'&&S.model!==nm)return;
    (byModel[nm]=byModel[nm]||{m:lookups[t.model_id],all:[],due:[]}).all.push(t);
    var k=key(t.due_at);if(inRange(k)||(new Date(t.due_at).getTime()<now&&k<weekKeys[0]))byModel[nm].due.push(t);
  });
  var names=Object.keys(byModel).filter(function(n){return byModel[n].due.length;}).sort(function(a,b){return new Date(byModel[a].due[0].due_at)-new Date(byModel[b].due[0].due_at);});
  var moveHtml=move.length?'<h4 class="mp-h">Movement <em>'+move.length+'</em></h4><div class="mp-list">'+move.map(function(x){var ms=displayModels(x),who=ms.length===1?ms[0].name:ms.length>1?ms.length+' models':'';
    return '<button type="button" class="mp-row k-travel" data-open="'+esc(x.kind)+'|'+esc(x.id)+'"><span class="mp-day"><small>'+esc(date(x.starts_at,{weekday:'short'}))+'</small><b>'+new Date(x.starts_at).getDate()+'</b></span><span class="mp-main"><b>'+esc(x.title||'Movement')+'</b><small>'+esc([who,x.location,time(x.starts_at)].filter(Boolean).join(' · '))+'</small></span><span class="pl-tag k-travel">'+esc(type(x))+'</span></button>';}).join('')+'</div>':'';
  var plansHtml=names.length?'<h4 class="mp-h">Plans <em>'+names.reduce(function(n,k){return n+byModel[k].due.length;},0)+' due</em></h4>'+names.map(function(nm){
    var g=byModel[nm],due=g.due.sort(function(a,b){return new Date(a.due_at)-new Date(b.due_at);}),hard=g.all.filter(function(t){return t.metadata&&t.metadata.is_hard_stop&&new Date(t.due_at).getTime()>=now;}).sort(function(a,b){return new Date(a.due_at)-new Date(b.due_at);})[0];
    var moves=move.filter(function(x){return models(x).some(function(m){return m.name===nm;});}).length;
    var base=g.m.primary_market_label||'';
    var meta=[base?'Base '+esc(base):'',g.all.length+' open',moves?moves+' moving':'',hard?'next hard stop '+esc(date(hard.due_at,{weekday:'short',month:'short',day:'numeric'})+' '+time(hard.due_at)):''].filter(Boolean).join(' · ');
    return '<div class="mp-model"><div class="mp-mh"><button type="button" class="mp-name" data-mp-model="'+esc(nm)+'" title="Open '+esc(nm)+'\'s calendar">'+esc(nm)+'</button><small>'+meta+'</small></div>'
      +due.slice(0,4).map(function(t){var over=new Date(t.due_at).getTime()<now;return '<button type="button" class="mp-task'+(over?' over':'')+'" data-tk-open="'+esc(t.id)+'"><span class="mp-due">'+esc(tkDue(t.due_at))+'<small>'+esc(time(t.due_at))+'</small></span><b>'+esc(t.title||'Task')+'</b>'+(t.metadata&&t.metadata.is_hard_stop?'<i class="mp-hard" title="Hard stop"></i>':'')+'<em>'+esc(mpLabel(t))+'</em></button>';}).join('')
      +(due.length>4?'<button type="button" class="tk-more" data-tk-open="">+ '+(due.length-4)+' more</button>':'')+'</div>';}).join(''):'';
  var empty=(!move.length&&!names.length)?'<p class="pl-none">No model plans or movement '+(day?'on this day':'this week')+(S.model!=='all'?' for '+esc(S.model):'')+'. Use ‹ › to look at another week.</p>':'';
  return hdr+moveHtml+plansHtml+empty;
}
function paintModels(){var el=document.getElementById('pl-models');if(el&&MP.last)el.innerHTML=modelsHtml(MP.last.items,MP.last.weekKeys,MP.last.sel);}
document.addEventListener('click',function(e){
  var b=e.target&&e.target.closest&&e.target.closest('#pl-models [data-mp-scope],#pl-models [data-tk-open],#pl-models [data-mp-model],.pl-split-host [data-tk-open],.pl-split-host [data-mp-model]');if(!b)return;
  if(b.dataset.mpScope){MP.scope=b.dataset.mpScope;paintModels();return;}
  if(b.dataset.mpModel){S.model=b.dataset.mpModel;S.selected=null;try{saveWorkspace();}catch(_e){}redrawCurrent();return;}
  if(b.hasAttribute('data-tk-open')&&typeof window.navTo==='function')window.navTo('tasksconsolidated');
});
/* Swipe the day card left or right to step through the week (phone). Crossing the end of the week turns the page. */
function stepDay(n){var nx=add(new Date(planSel()+'T12:00:00'),n),r=range(),k=key(nx);S.planDay=k;S.selected=null;if(k<key(r.start)||k>key(add(r.start,6))){S.anchor=nx;render();}else redrawCurrent();}
(function(){var sx=0,sy=0,st=0;
  document.addEventListener('touchstart',function(e){var c=e.target&&e.target.closest&&e.target.closest('.mdv-plan .pl-card');if(!c||e.touches.length!==1){sx=0;return;}sx=e.touches[0].clientX;sy=e.touches[0].clientY;st=Date.now();},{passive:true});
  document.addEventListener('touchend',function(e){if(!sx)return;var t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;sx=0;if(Math.abs(dx)<70||Math.abs(dy)>45||Date.now()-st>700)return;if(window.getSelection&&String(window.getSelection()))return;
    var card=document.querySelector('.mdv-plan .pl-card');if(card)card.style.setProperty('--pl-from',dx<0?'28px':'-28px');stepDay(dx<0?1:-1);},{passive:true});
})();
/* ---------- Split: the team's day on the left, the models' day on the right, with clashes called out ---------- */
function splitOn(){try{return localStorage.getItem('mdv-agenda-split')==='1';}catch(e){return false;}}
function splitSet(v){try{localStorage.setItem('mdv-agenda-split',v?'1':'0');}catch(e){}}
function timeOverlap(a,b){var as=+new Date(a.starts_at),ae=+new Date(a.ends_at||as+3600000),bs=+new Date(b.starts_at),be=+new Date(b.ends_at||bs+3600000);return as<be&&bs<ae;}
function splitHasData(day,sel){if(day.length)return true;var look={};arr(S.data&&S.data.lookups&&S.data.lookups.models).forEach(function(m){look[m.id]=m.display_name;});return arr(TK.list).some(function(t){return t.model_id&&look[t.model_id]&&mpOpenTask(t)&&t.due_at&&key(t.due_at)===sel&&(S.model==='all'||S.model===look[t.model_id]);});}
function splitHtml(day,sel,nowMs){
  /* the team column ignores the model filter: picking one model should still show your own day beside theirs */
  var team=arr(S.items).filter(function(x){return key(x.starts_at)===sel&&!models(x).length;}).sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);}),mod=day.filter(function(x){return models(x).length;});
  var look={};arr(S.data&&S.data.lookups&&S.data.lookups.models).forEach(function(m){look[m.id]=m.display_name;});
  var by={},order=[];
  function add(n,it){if(!by[n]){by[n]={ev:[],tk:[]};order.push(n);}by[n][it.task?'tk':'ev'].push(it.task||it.x);}
  mod.forEach(function(x){models(x).forEach(function(m){add(m.name,{x:x});});});
  arr(TK.list).filter(function(t){return t.model_id&&look[t.model_id]&&mpOpenTask(t)&&t.due_at&&key(t.due_at)===sel;}).forEach(function(t){var n=look[t.model_id];if(S.model==='all'||S.model===n)add(n,{task:t});});
  var clashes=mod.filter(function(x){return team.some(function(y){return timeOverlap(x,y);});});
  var tkN=order.reduce(function(n,k){return n+by[k].tk.length;},0),first=mod.slice().sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);})[0];
  var bits=[];
  if(mod.length||tkN)bits.push('<b>'+mod.length+'</b> model item'+(mod.length===1?'':'s')+(tkN?' and <b>'+tkN+'</b> plan deadline'+(tkN===1?'':'s'):''));
  if(first)bits.push('first at '+esc(time(first.starts_at)));
  var smart=bits.length?'<div class="pl-smart"><span class="pl-veuxi">✦ Veux</span><span>'+bits.join(' · ')+'. '+(clashes.length?'<em class="risk">'+clashes.length+' overlap'+(clashes.length===1?'s':'')+' your day: '+esc(clashes[0].title||'event')+' at '+esc(time(clashes[0].starts_at))+'</em>':'No clashes with your day.')+'</span></div>':'';
  var left=team.length?team.map(function(x,i){return planRow(x,i,team,nowMs);}).join(''):'<p class="pl-none">Nothing for the team that is not tied to a model.</p>';
  var right=order.length?order.map(function(n){var g=by[n];
    return '<div class="pl-mgroup"><div class="pl-mh"><button type="button" class="mp-name" data-mp-model="'+esc(n)+'" title="Open '+esc(n)+'\'s calendar">'+esc(n)+'</button></div>'
      +g.ev.map(function(x){var hit=team.filter(function(y){return timeOverlap(x,y);})[0];return planRow(x,0,[x].concat(team),nowMs)+(hit?'<div class="pl-xclash">Overlaps your '+esc(hit.title||'event')+' ('+esc(time(hit.starts_at))+')</div>':'');}).join('')
      +g.tk.map(function(t){return '<button type="button" class="mp-task" data-tk-open="'+esc(t.id)+'"><span class="mp-due">Due<small>'+esc(time(t.due_at))+'</small></span><b>'+esc(t.title||'Task')+'</b>'+(t.metadata&&t.metadata.is_hard_stop?'<i class="mp-hard" title="Hard stop"></i>':'<i></i>')+'<em>'+esc(mpLabel(t))+'</em></button>';}).join('')+'</div>';}).join(''):'<p class="pl-none">No model events or plan deadlines today.</p>';
  return smart+'<div class="pl-cols"><section class="pl-col"><h3>Team &amp; agency <em>'+team.length+'</em></h3>'+left+'</section><section class="pl-col models"><h3>Models <em>'+(mod.length+tkN)+'</em></h3>'+right+'</section></div>';
}
document.addEventListener('click',function(e){var b=e.target&&e.target.closest&&e.target.closest('[data-ag-split]');if(!b)return;splitSet(!splitOn());redrawCurrent();});
function planPanels(sel){try{if(window.MDV_SCHEDULE&&MDV_SCHEDULE.embeddedHtml)return MDV_SCHEDULE.embeddedHtml(S.items,sel);}catch(e){console.error('[calendar] panels',e);}return '';}
function planView(items){
  var r=range(),nowMs=Date.now(),todayKey=key(new Date()),sel=planSel(),typeF=S.agendaType||'all';
  var every=items.slice().sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);});
  var counts={all:every.length};PLAN_KINDS.forEach(function(q){counts[q[0]]=every.filter(function(x){return agendaKindOf(x)===q[0];}).length;});
  var all=typeF==='all'?every:every.filter(function(x){return agendaKindOf(x)===typeF;});
  var weekKeys=[];for(var i=0;i<7;i++)weekKeys.push(key(add(r.start,i)));
  var week=all.filter(function(x){return weekKeys.indexOf(key(x.starts_at))>=0;});
  var hrs=week.reduce(function(n,x){return n+planHrs(x);},0),working={};week.forEach(function(x){models(x).forEach(function(m){working[m.name]=1;});});
  /* one slim toolbar: who, which season, what kind, and the main action */
  var names=modelNames(),modelSel='<select class="pl-sel" data-ag-model aria-label="Model"><option value="all">All models ('+names.length+')</option>'+names.map(function(n){return '<option value="'+esc(n)+'"'+(S.model===n?' selected':'')+'>'+esc(n)+'</option>';}).join('')+'</select>';
  var peopleSel=S.people.length?'<select class="pl-sel" data-ag-person aria-label="Team member"><option value="all">Everyone ('+S.people.length+')</option>'+S.people.map(function(n){return '<option value="'+esc(n)+'"'+(S.person===n?' selected':'')+'>'+esc(n)+'</option>';}).join('')+'</select>':'';
  var seasonSel=S.seasonList.length?'<select class="pl-sel" data-pl-season aria-label="Season"><option value="none"'+(S.season==='none'?' selected':'')+'>Agency only</option>'+S.seasonList.map(function(z){return '<option value="'+esc(z.id)+'"'+(S.season===z.id?' selected':'')+'>'+esc(z.name)+'</option>';}).join('')+'<option value="all"'+(S.season==='all'?' selected':'')+'>All seasons</option></select>':'';
  var kindLabel={booking:'Bookings',casting:'Castings',travel:'Travel',other:'Other'},kinds=[['all','All']].concat(PLAN_KINDS.map(function(q){return [q[0],kindLabel[q[0]]];})).filter(function(c){return c[0]==='all'||counts[c[0]];});
  var kindChips='<div class="pl-seg" role="group" aria-label="Show">'+kinds.map(function(c){return '<button type="button" class="'+(typeF===c[0]?'on':'')+'" data-ag-type="'+c[0]+'">'+c[1]+' <em>'+counts[c[0]]+'</em></button>';}).join('')+'</div>';
  var splitBtn='<button type="button" class="pl-splitbtn'+(splitOn()?' on':'')+'" data-ag-split aria-pressed="'+(splitOn()?'true':'false')+'" title="Team on the left, models on the right">Split</button>';
  var bar='<div class="pl-bar">'+peopleSel+modelSel+seasonSel+kindChips+splitBtn+'<button type="button" class="pl-primary" data-act="fullbooking">+ Full booking</button></div>';
  /* one summary line (no repeated tiles) */
  var sigs=planSignals(week),sigHtml=sigs.map(function(g){return '<button type="button" class="pl-sig '+g.sev+'" data-pl-go="'+g.day+'">'+esc(g.text)+'</button>';}).join('');
  var strip='<div class="pl-strip"><span class="pl-facts"><b>'+uq(week).length+'</b> event'+(uq(week).length===1?'':'s')+' this week<i>·</i><b>'+planH(hrs)+'</b> scheduled<i>·</i><b>'+Object.keys(working).length+'</b> model'+(Object.keys(working).length===1?'':'s')+'</span>'+(sigHtml?'<span class="pl-signals"><span class="pl-veuxi">✦ Veux</span>'+sigHtml+'</span>':'')+'</div>';
  var pills=weekKeys.map(function(k,i){
    var d=add(r.start,i),n=week.filter(function(x){return key(x.starts_at)===k;}).length;
    return '<button type="button" class="pl-pill'+(k===sel?' on':'')+(k===todayKey?' today':'')+(n?'':' free')+'" data-pl-day="'+k+'" data-vx-drop-day="'+k+'" aria-pressed="'+(k===sel?'true':'false')+'"><small>'+esc(date(d,{weekday:'short'}))+'</small><b>'+d.getDate()+'</b><span class="pl-dot'+(n?' has':'')+'" title="'+n+' event'+(n===1?'':'s')+'">'+(n||'')+'</span></button>';
  }).join('');
  var day=all.filter(function(x){return key(x.starts_at)===sel;}),sd=new Date(sel+'T12:00:00'),isToday=sel===todayKey;
  var byKind={};day.forEach(function(x){var k=agendaKindOf(x);byKind[k]=(byKind[k]||0)+1;});
  var chips=PLAN_KINDS.filter(function(q){return byKind[q[0]];}).map(function(q){return '<span class="pl-chip k-'+q[0]+'">'+byKind[q[0]]+' '+q[1].toLowerCase()+(byKind[q[0]]===1?'':'s')+'</span>';}).join('');
  var dayHrs=day.reduce(function(n,x){return n+planHrs(x);},0),nowLine=false;
  var rowsHtml=day.map(function(x,i){var line='';if(isToday&&!nowLine&&new Date(x.starts_at).getTime()>nowMs){nowLine=true;line='<div class="pl-now"><span>Now · '+esc(time(new Date()))+'</span></div>';}return line+planRow(x,i,day,nowMs);}).join('');
  if(isToday&&day.length&&!nowLine)rowsHtml+='<div class="pl-now"><span>Now · '+esc(time(new Date()))+'</span></div>';
  var card='<section class="pl-card'+(splitOn()?' pl-split-host':'')+'"><header><h2>'+esc(date(sd,{weekday:'long'}))+'</h2><small>'+esc(date(sd,{month:'long',day:'numeric'}))+'</small>'+(isToday?'<span class="pl-today">Today</span>':'')+'<span class="pl-meta">'+day.length+' event'+(day.length===1?'':'s')+(dayHrs?' · '+planH(dayHrs):'')+'</span></header>'
    +(chips?'<div class="pl-chips">'+chips+'</div>':'')
    +(splitOn()&&splitHasData(day,sel)?splitHtml(day,sel,nowMs):day.length?'<div class="pl-rows">'+rowsHtml+'</div>':'<div class="pl-empty"><b>'+(isToday?'Nothing scheduled today':'A free day')+'</b><span>Add an event, or drag one here from another day.</span><button type="button" class="pl-primary" data-act="add-day" data-day="'+sel+'">+ Add an event</button></div>')+'</section>';
  return '<div class="mdv-plan">'+bar+strip+'<nav class="pl-pills" aria-label="Days this week">'+pills+'</nav>'
    +'<div class="pl-grid"><div class="pl-left">'+card+'<section class="pl-side pl-models" id="pl-models">'+modelsHtml(every,weekKeys,sel)+'</section><section class="pl-side pl-tasks" id="pl-tasks" data-tkday="'+sel+'">'+tasksHtml(sel)+'</section></div><aside class="pl-right" data-pl-panels>'+planPanels(sel)+'</aside></div></div>';
}
